const CODE_ORDER = Object.fromEntries(TOPICS.map((t,i)=>[t.code,i]));
function hwToProblem(t, hw){
  if(hw.kind==="solve") return {code:t.code, level:"база", title:hw.title, problem:hw.cond, steps:hw.steps, answer:hw.answer};
  if(hw.kind==="fill") return {code:t.code, level:"база", title:hw.title, problem:hw.cond, steps:hw.items.map(it=>[it[0],it[1]]), answer:"Сверьте формулировки определений выше."};
  if(hw.kind==="classify") return {code:t.code, level:"сложно", title:hw.title, problem:hw.cond, steps:hw.lines.map(l=>[l.label+" ("+fmt(l.amount)+")", (l.correct==="in"?"Включается. ":"Не включается. ")+l.note]), answer:"Включается "+fmt(hw.answerIn)+", не включается "+fmt(hw.answerOut)+"."};
  return {code:t.code, level:"база", title:hw.title, problem:hw.cond, steps:hw.steps||[], answer:hw.answer||""};
}
const EXAM_PROBLEMS = (()=>{
  const out=[];
  TOPICS.forEach(t=>{
    t.examples.forEach(ex=>out.push({code:t.code, level:"база", title:ex.title, problem:ex.problem, steps:ex.steps, answer:ex.answer}));
    t.homeworks.forEach(hw=>out.push(hwToProblem(t,hw)));
  });
  HARD_PROBLEMS.forEach(p=>out.push({...p}));
  const lv={"база":0,"сложно":1};
  return out.map((p,i)=>({...p,_i:i})).sort((a,b)=> (CODE_ORDER[a.code]-CODE_ORDER[b.code]) || (lv[a.level]-lv[b.level]) || (a._i-b._i));
})();
const EXAM_TEST_POOL = (()=>{
  const all=[];
  TOPICS.forEach(t=>t.quiz.forEach(q=>{ if(!q.open && q.options) all.push({...q,code:t.code}); }));
  EXTRA_TESTS.forEach(q=>all.push({...q}));
  return all;
})();

export { fmt, TOPICS, TMAP, HARD_PROBLEMS, EXTRA_TESTS, EXAM_PROBLEMS, EXAM_TEST_POOL };
